import{_ as l,o as a,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2023-01-12","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-01-12","date":"2023-01-12T00:00:00.000Z","updated":"2023-01-13T00:00:00.000Z","tags":["Ceph","分布式存储","RocksDB","性能优化","研究讨论"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-01-12.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-01-12.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Ceph_Performance_Meeting_2023-01-12.md"};function r(s,e,n,u,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要讨论了Ceph存储系统的多个Pull Request（PR），包括优先操作、RocksDB迭代器平衡、删除范围操作的改进等。此外，会议还探讨了未来的研究方向和计划，并对Blue Store中的快照和对象克隆进行了优化讨论。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><strong>Pull Request讨论</strong><ul><li><strong>优先操作PR</strong>：讨论了新的PR，涉及优先操作和插件。</li><li><strong>RocksDB迭代器平衡PR</strong>：Corey的PR，关于设置RocksDB迭代器的平衡或集合列表。</li><li><strong>删除范围操作改进</strong>：讨论了升级到最新版本的RocksDB，以改进删除范围操作，特别是针对memtable的刷新。</li></ul></li><li><strong>RocksDB迭代器行为</strong><ul><li>讨论了使用无界迭代器导致的性能问题，并提出了添加边界迭代器的解决方案。</li><li>讨论了在特定情况下（如PG移动）使用单个删除操作的必要性。</li></ul></li><li><strong>研究方向和计划</strong><ul><li>讨论了恢复研究讨论的计划，包括定期讨论相关研究论文和想法。</li><li>提出了使用性能调用或其他会议时间来讨论研究主题的建议。</li></ul></li><li><strong>Blue Store优化</strong><ul><li>讨论了Blue Store中快照和对象克隆的优化进展，包括减少共享blob的数量和优化克隆操作。</li><li>提到了Adam Kupchak的工作，他在改进快照和对象克隆的性能方面取得了进展。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续审查和测试涉及RocksDB迭代器和删除范围操作的PR。</li><li>确定了恢复研究讨论的计划，并计划定期讨论相关研究论文。</li><li>继续推进快照和对象克隆在Blue Store中的优化工作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>对涉及RocksDB迭代器和删除范围操作的PR进行进一步的测试和审查。</li><li>组织定期的研究讨论会议，收集和讨论相关的研究论文和想法。</li><li>继续推进快照和对象克隆在Blue Store中的优化工作。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>讨论了Adam Kupchak在优化快照和对象克隆方面的进展。</li><li>讨论了使用RocksDB的deadline参数来检测是否有过多的墓碑（tombstones）和迭代时间过长的问题。</li></ul><p>会议结束时，大家对未来的研究讨论表示期待，并计划在下次会议中继续跟进相关进展。</p>',12)])])}const p=l(o,[["render",r]]);export{_ as __pageData,p as default};
